proc stepEncLcnApCommitment*(w: var EncWork, src: pointer, dst: ptr CborValue) =
  let x {.used.} = cast[ptr LcnApCommitment](src)
  var n = 0
  if x.request.isSome:
    inc n
  if x.response.isSome:
    inc n
  let node = CborValue(kind: ckMap, entries: newSeq[CborEntry](n))
  dst[] = node
  var k = 0
  if x.request.isSome:
    node.entries[k].key = cbor("request")
    node.entries[k].value = cbor("retain-root")
    inc k
  if x.response.isSome:
    node.entries[k].key = cbor("response")
    node.entries[k].value = cbor("retain-root")
    inc k

proc stepDecLcnApCommitment*(w: var DecWork, v: CborValue, dst: pointer) =
  let r = cast[ptr LcnApCommitment](dst)
  r[] = LcnApCommitment()
  let f19 = v.lookup("request")
  if f19.isSome:
    r.request = Opt.some("retain-root")
  let f20 = v.lookup("response")
  if f20.isSome:
    r.response = Opt.some("retain-root")

proc toCbor*(x: LcnApCommitment): CborValue =
