proc stepEncLcnDcPolicyARCapabilityAuthorityMap*(w: var EncWork, src: pointer, dst: ptr CborValue) =
  let x {.used.} = cast[ptr LcnDcPolicyARCapabilityAuthorityMap](src)
  var n = 3
  if x.audit.isSome:
    inc n
  if x.decision_validity_ms.isSome:
    inc n
  if x.evaluation_deadline_ms.isSome:
    inc n
  if x.recovery.isSome:
    inc n
  let node = CborValue(kind: ckMap, entries: newSeq[CborEntry](n))
  dst[] = node
  var k = 0
  if x.audit.isSome:
    node.entries[k].key = cbor("audit")
    w.later(stepEncLcnDcPolicyARCapabilityAuthorityAuditMap, addr x.audit.get, addr node.entries[k].value)
    inc k
  if x.decision_validity_ms.isSome:
    node.entries[k].key = cbor("decision_validity_ms")
    node.entries[k].value = cbor(uint64(x.decision_validity_ms.get))
    inc k
  if x.evaluation_deadline_ms.isSome:
    node.entries[k].key = cbor("evaluation_deadline_ms")
    node.entries[k].value = cbor(uint64(x.evaluation_deadline_ms.get))
    inc k
  node.entries[k].key = cbor("kind")
  node.entries[k].value = cbor("capability-authority")
  inc k
  if x.recovery.isSome:
    node.entries[k].key = cbor("recovery")
    node.entries[k].value = cbor(x.recovery.get)
    inc k
  node.entries[k].key = cbor("rules")
  let a256 = newCborArray(x.rules.len)
  node.entries[k].value = a256
  for i257 in 0 ..< x.rules.len:
    w.later(stepEncLcnApRule, addr x.rules[i257], addr a256.items[i257])
  inc k
  node.entries[k].key = cbor("source")
  node.entries[k].value = cbor(x.source)
  inc k

