    r.audit = Opt.some(default(LcnDcPolicyARCapabilityAuthorityAuditMap))
    w.later(stepDecLcnDcPolicyARCapabilityAuthorityAuditMap, f252.get, addr r.audit.get)
  let f253 = v.lookup("decision_validity_ms")
  if f253.isSome:
