proc stepEncLcnDcPolicy*(w: var EncWork, src: pointer, dst: ptr CborValue) =
  let x {.used.} = cast[ptr LcnDcPolicy](src)
  case x.kind
  of LcnDcPolicyKind.Allow_all:
    w.later(stepEncLcnDcPolicyARAllowAllMap, addr x.arm_Allow_all, addr dst[])
  of LcnDcPolicyKind.Capability_authority:
    w.later(stepEncLcnDcPolicyARCapabilityAuthorityMap, addr x.arm_Capability_authority, addr dst[])

proc stepDecLcnDcPolicy*(w: var DecWork, v: CborValue, dst: pointer) =
  let r = cast[ptr LcnDcPolicy](dst)
  case generatedSchema().arm("lcn.dc_policy#", v)
  of 0:
    r[] = LcnDcPolicy(kind: LcnDcPolicyKind.Allow_all)
    w.later(stepDecLcnDcPolicyARAllowAllMap, v, addr r.arm_Allow_all)
  of 1:
    r[] = LcnDcPolicy(kind: LcnDcPolicyKind.Capability_authority)
    w.later(stepDecLcnDcPolicyARCapabilityAuthorityMap, v, addr r.arm_Capability_authority)
  else:
    raiseAssert "a checked value selects a known arm"

