proc stepEncLcnDcRestart*(w: var EncWork, src: pointer, dst: ptr CborValue) =
  let x {.used.} = cast[ptr LcnDcRestart](src)
  case x.kind
  of LcnDcRestartKind.Backoff:
    w.later(stepEncLcnDcRestartARBackoffMap, addr x.arm_Backoff, addr dst[])
  of LcnDcRestartKind.Disabled:
    w.later(stepEncLcnDcRestartARDisabledMap, addr x.arm_Disabled, addr dst[])

proc stepDecLcnDcRestart*(w: var DecWork, v: CborValue, dst: pointer) =
  let r = cast[ptr LcnDcRestart](dst)
  case generatedSchema().arm("lcn.dc_restart#", v)
  of 0:
    r[] = LcnDcRestart(kind: LcnDcRestartKind.Disabled)
    w.later(stepDecLcnDcRestartARDisabledMap, v, addr r.arm_Disabled)
  of 1:
    r[] = LcnDcRestart(kind: LcnDcRestartKind.Backoff)
    w.later(stepDecLcnDcRestartARBackoffMap, v, addr r.arm_Backoff)
  else:
    raiseAssert "a checked value selects a known arm"

