proc stepEncLcnDcTestHooks*(w: var EncWork, src: pointer, dst: ptr CborValue) =
  let x {.used.} = cast[ptr LcnDcTestHooks](src)
  var n = 0
  if x.ctl_command_delay_ms.isSome:
    inc n
  if x.diagnostics.isSome:
    inc n
  if x.loader_failure_after_ms.isSome:
    inc n
  if x.loader_failure_on_file.isSome:
    inc n
  let node = CborValue(kind: ckMap, entries: newSeq[CborEntry](n))
  dst[] = node
  var k = 0
  if x.ctl_command_delay_ms.isSome:
    node.entries[k].key = cbor("ctl_command_delay_ms")
    node.entries[k].value = cbor(uint64(x.ctl_command_delay_ms.get))
    inc k
  if x.diagnostics.isSome:
    node.entries[k].key = cbor("diagnostics")
    w.later(stepEncLcnDcTestDiagnostics, addr x.diagnostics.get, addr node.entries[k].value)
    inc k
  if x.loader_failure_after_ms.isSome:
    node.entries[k].key = cbor("loader_failure_after_ms")
    node.entries[k].value = cbor(uint64(x.loader_failure_after_ms.get))
    inc k
  if x.loader_failure_on_file.isSome:
    node.entries[k].key = cbor("loader_failure_on_file")
    node.entries[k].value = encLcnAppPath(x.loader_failure_on_file.get)
    inc k

proc stepDecLcnDcTestHooks*(w: var DecWork, v: CborValue, dst: pointer) =
  let r = cast[ptr LcnDcTestHooks](dst)
  r[] = LcnDcTestHooks()
  let f271 = v.lookup("ctl_command_delay_ms")
  if f271.isSome:
    r.ctl_command_delay_ms = Opt.some(uint32(f271.get.uint))
  let f272 = v.lookup("diagnostics")
  if f272.isSome:
    r.diagnostics = Opt.some(default(LcnDcTestDiagnostics))
    w.later(stepDecLcnDcTestDiagnostics, f272.get, addr r.diagnostics.get)
  let f273 = v.lookup("loader_failure_after_ms")
  if f273.isSome:
    r.loader_failure_after_ms = Opt.some(uint32(f273.get.uint))
  let f274 = v.lookup("loader_failure_on_file")
  if f274.isSome:
    r.loader_failure_on_file = Opt.some(decLcnAppPath(f274.get))

proc toCbor*(x: LcnDcTestHooks): CborValue =
  runEnc(stepEncLcnDcTestHooks, addr x)

proc fromChecked*(T: type LcnDcTestHooks, v: CborValue): LcnDcTestHooks =
  var r: LcnDcTestHooks
  runDec(stepDecLcnDcTestHooks, v, addr r)
  r

